## Approach
Count frequencies of characters using a fixed frequency array of size 26 for lowercase English letters. Increment frequency for characters in string `s` and decrement for characters in string `t`.

## Algorithm
Character Frequency Array Hashing

## Code
```c
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

bool isAnagram(const char* s, const char* t) {
 if (strlen(s) != strlen(t)) return false;
 int count[26] = {0};
 for (int i = 0; s[i] != '\0'; i++) {
 count[s[i] - 'a']++;
 count[t[i] - 'a']--;
 }
 for (int i = 0; i < 26; i++) {
 if (count[i] != 0) return false;
 }
 return true;
}

int main() {
 printf("%d\n", isAnagram("anagram", "nagaram"));
 return 0;
}
```

