## Approach
Use a sliding window with two pointers (`left` and `right`) and a Set to track characters in the current window. Expand right pointer and shrink left pointer whenever a duplicate character is encountered.

## Algorithm
Sliding Window Hash Set

## Code
```javascript
function lengthOfLongestSubstring(s) {
 let set = new Set();
 let left = 0, maxLen = 0;
 for (let right = 0; right < s.length; right++) {
 while (set.has(s[right])) {
 set.delete(s[left]);
 left++;
 }
 set.add(s[right]);
 maxLen = Math.max(maxLen, right - left + 1);
 }
 return maxLen;
}
console.log(lengthOfLongestSubstring('abcabcbb'));
```

