## Approach
Maintain a min-heap containing the current head node of each of the k linked lists. Extract the minimum node repeatedly and insert its next node into the min-heap.

## Algorithm
Min-Heap Priority Queue Merge

## Code
```go
package main

import (
 "container/heap"
 "fmt"
)

type ListNode struct {
 Val int
 Next *ListNode
}

type PriorityQueue []*ListNode

func (pq PriorityQueue) Len() int { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool { return pq[i].Val < pq[j].Val }
func (pq PriorityQueue) Swap(i, j int) { pq[i], pq[j] = pq[j], pq[i] }
func (pq *PriorityQueue) Push(x interface{}) {
 *pq = append(*pq, x.(*ListNode))
}
func (pq *PriorityQueue) Pop() interface{} {
 old := *pq
 n := len(old)
 item := old[n-1]
 *pq = old[0 : n-1]
 return item
}

func mergeKLists(lists []*ListNode) *ListNode {
 pq := &PriorityQueue{}
 heap.Init(pq)
 for _, list := range lists {
 if list != nil {
 heap.Push(pq, list)
 }
 }
 dummy := &ListNode{}
 curr := dummy
 for pq.Len() > 0 {
 node := heap.Pop(pq).(*ListNode)
 curr.Next = node
 curr = curr.Next
 if node.Next != nil {
 heap.Push(pq, node.Next)
 }
 }
 return dummy.Next
}

func main() {
 fmt.Println("Merge K Lists Heap Execution")
}
```

