## Approach
Validate pointer initialization and handle null boundary conditions before accessing `next` pointers.

## Algorithm
Memory Safety Guard & Pointer Check

## Code
```c++
#include <iostream>
struct ListNode {
 int val;
 ListNode* next;
 ListNode(int x) : val(x), next(nullptr) {}
};
ListNode* reverseList(ListNode* head) {
 if (!head || !head->next) return head;
 ListNode* prev = nullptr;
 ListNode* curr = head;
 while (curr) {
 ListNode* nextTemp = curr->next;
 curr->next = prev;
 prev = curr;
 curr = nextTemp;
 }
 return prev;
}
```

